/**
* Removes the change event handler (actually ALL handlers) from the selectTheArtist element
*/
$j( document ).ready(function() {
var oacartists = $j("#oacartists"),
hasNoYTRequest	= $j('#hasNoYTRequest'),
hasYTRequest	= $j('#hasYTRequest'),
youtubeChannel0 = $j('#youtubeChannel0'),
youtubeChannel3 = $j('#youtubeChannel3'),
confirmYTChannelSelectionButton	= $j('#confirmYTChannelSelectionButton'),
selectADifferentChannelButton	= $j('#selectADifferentChannelButton'),
doesArtistHaveChannel	= $j('.doesArtistHaveChannel'),
youTubeAccessToken	= $j('#youTubeAccessToken'),
youTubeRefreshToken	= $j('#youTubeRefreshToken'),
myBandName	= $j('.myBandName');
$j( '#gSignInWrapper' ).show();
$j( '#gConnectedToWrapper' ).hide();
$( '#customGoogleSignInButton' ).click( function(){
window.open( '/api/googleoauth', '_blank', 'width=500,height=600' );
} );
function changedArtist(){
$j( '#YTArtistWrapper' ).show();
$j( '#YTChannelSpinner' ).show();
var selectedArtistName = $j( '.selectTheArtist option:selected' ).val();
$j( '#artistName' ).val( selectedArtistName );
// Force hiding the Google OAuth UI elements
$j( '#gSignInWrapper' ).hide();
$j( '#gConnectedToWrapper' ).hide();
$j ('#qChannelWrapper' ).hide();
$j( '#youTubeChannelId' ).val( '' ); // clear it out
$j( '#youTubeChannelName' ).val( '' ); // clear it out
$j( '#youTubeChannelURL' ).val( '' ); // clear it out
if (selectedArtistName != '') {
$j.ajax( {
url: '/api/checkYTArtistChannel/',
type: 'get',
data: {
artistName: selectedArtistName
},
success: function( response ){
doesArtistHaveChannel.show();
var responseData = $j.parseJSON( response );
if( responseData.hasYTRequest ){
hasYTRequest.show();
hasNoYTRequest.hide();
} else {
hasNoYTRequest.show();
hasYTRequest.hide();
}
if( !responseData.hasYTChannelData ){
$j( '.noYTChannelData' ).hide();
} else {
$j( '.noYTChannelData' ).show();
}
$j( '#YTChannelSpinner' ).hide();
myBandName.text(selectedArtistName);
$j( '#qChannelWrapper' ).show();
}
} );	
} else {
initArtist();
}
} 
function initArtist(){
$j( '.selectTheArtist' ).val('');
oacartists.on('change', function(){ changedArtist()});
hasNoYTRequest.hide();
youtubeChannel0.prop('checked', true);
doesArtistHaveChannel.show();
youTubeAccessToken.val('');
youTubeRefreshToken.val('');
}
selectADifferentChannelButton.click(function(){
hasYTRequest.hide();
hasNoYTRequest.show();
doesArtistHaveChannel.hide();
youtubeChannel3.prop('checked', true);
// youtubeChannelSelector();
});
/**
* Removes all UI elements for the YT Channel Selection
*/
function hideGoogleConnectUI(){
$j( '#YTArtistWrapper' ).hide();
$j( '#gSignInWrapper' ).hide();
$j( '#gConnectedToWrapper' ).hide();
$j( '#qChannelWrapper' ).hide();
$j( '#hasNoYTRequest' ).hide();
$j( '#hasYTRequest' ).hide();
$j( '#qChannelWrapper' ).hide();
$j( '.channelSelectButton' ).hide();
}
